using Microsoft.EntityFrameworkCore;using Microsoft.OpenApi;using Pedidos.Api.Data;var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddDbContext<PedidosDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("PedidosConnection")));builder.Services.AddHttpClient();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>o.SwaggerDoc("v1",new OpenApiInfo{Title="Pedidos.Api",Version="v1"}));builder.Services.AddCors(o=>o.AddPolicy("LocalSwagger",policy=>policy.WithOrigins("http://localhost:5149").AllowAnyHeader().AllowAnyMethod())); var app=builder.Build();app.UseCors("LocalSwagger"); if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.MapGet("/health",()=>Results.Ok(new{servicio="Pedidos.Api",estado="activo"}));app.MapControllers();app.Run();

